it('keeps rejected dynamic input values private specs/hal-engine-tool-input-validation/spec.md#2', async () => {
  const log = jest.fn();
  setLogger({debug: log, info: log, warn: log, error: log});
  try {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'accepted');
    registry.register(
      () => ({
        name: 'dynamic',
        description: 'Dynamic',
        inputSchema: {type: 'object', properties: {location: {type: 'number'}}},
      }),
      execute
    );
    const response = await registry.execute('dynamic', {location: 'private-value'});
    expect({
      result: response.result,
      leaked: JSON.stringify({response, calls: log.mock.calls}).includes('private-value'),
      calls: execute.mock.calls.length,
    }).toEqual({
      result: expect.stringMatching(/location.*number/),
      leaked: false,
      calls: 0,
    });
  } finally {
    setLogger();
  }
